#!/usr/bin/env python3
import base64
B={'low9_score.py': '', 'low9_dashboard_builder.py': '', 'low9_occ.py': '', 'low9_pe_list.py': '', 'low9_score_model.py': ''}
for name, b in B.items():
    open(name, "wb").write(base64.b64decode(b))
    print("  [ok] wrote", name)
print("DONE. Next: git add -A && git commit -m 'v2: factor tags + retraining' && git push")
